    // First counted loop: i from 0 to 9, acc += 1 each iteration
    {
        let mut i: u64 = 0;
        // "Ghost" variable (runtime in Rust): g == acc - i
        let mut g: u64 = acc - i;

        while i < 10 {
            // Invariants (checked at runtime here)
            debug_assert!(i <= 10);
            debug_assert!(g < 100);
            debug_assert_eq!(g, acc - i);

            // Body
            i += 1;
            acc += 1;

            // Maintain ghost relation for next iteration
            g = acc - i;

            // Termination variant would be (10 - i), strictly decreases as i increases.
        }

        // Post-loop invariants can be checked too
        debug_assert!(i == 10);
        debug_assert_eq!(g, acc - i);
    }

